CREATE UNIQUE INDEX shot_reference_packs_one_active
    ON shot_reference_packs(storyboard_shot_id)
    WHERE status = 'active';

CREATE TABLE shot_reference_pack_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
