-- migration 000037_provider_model_deletion_rollback.sql sha256:0781cf81058adf6192cffed0cfeb9458d1348418b67a945908c29ec1c045acde
BEGIN;
SET search_path TO public;

CREATE TABLE provider_model_deletion_tombstones (
    provider_model_id UUID PRIMARY KEY,
    provider_account_id UUID NOT NULL REFERENCES provider_accounts(id) ON DELETE CASCADE,
    model_key TEXT NOT NULL,
    display_name TEXT NOT NULL,
    modality TEXT NOT NULL,
    original_status TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    deleted_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE provider_model_deletion_render_plan_references (
    video_render_plan_id UUID PRIMARY KEY REFERENCES video_render_plans(id) ON DELETE CASCADE,
    provider_model_id UUID NOT NULL REFERENCES provider_model_deletion_tombstones(provider_model_id) ON DELETE CASCADE,
    captured_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Migration 000036 may have been active before deletion snapshots existed.
-- Preserve already-null Render Plans with deterministic disabled placeholders.
INSERT INTO provider_model_deletion_tombstones(
    provider_model_id, provider_account_id, model_key, display_name,
    modality, original_status, created_at, updated_at, deleted_at
)
SELECT gen_random_uuid(), plan.provider_account_id,
       '__deleted_render_plan_' || replace(plan.id::text, '-', ''),
       'Deleted Render Plan Model', 'video', 'disabled',
       plan.created_at, plan.updated_at, plan.updated_at
FROM video_render_plans plan
WHERE plan.provider_model_id IS NULL;

INSERT INTO provider_model_deletion_render_plan_references(video_render_plan_id, provider_model_id)
SELECT plan.id, tombstone.provider_model_id
FROM video_render_plans plan
JOIN provider_model_deletion_tombstones tombstone
  ON tombstone.provider_account_id = plan.provider_account_id
 AND tombstone.model_key = '__deleted_render_plan_' || replace(plan.id::text, '-', '')
WHERE plan.provider_model_id IS NULL;

CREATE FUNCTION cineweave_capture_provider_model_deletion()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
    INSERT INTO provider_model_deletion_tombstones(
        provider_model_id, provider_account_id, model_key, display_name,
        modality, original_status, created_at, updated_at, deleted_at
    )
    VALUES (
        OLD.id, OLD.provider_account_id, OLD.model_key, OLD.display_name,
        OLD.modality, OLD.status, OLD.created_at, OLD.updated_at, now()
    )
    ON CONFLICT (provider_model_id) DO UPDATE
    SET provider_account_id = EXCLUDED.provider_account_id,
        model_key = EXCLUDED.model_key,
        display_name = EXCLUDED.display_name,
        modality = EXCLUDED.modality,
        original_status = EXCLUDED.original_status,
        created_at = EXCLUDED.created_at,
        updated_at = EXCLUDED.updated_at,
        deleted_at = EXCLUDED.deleted_at;

    INSERT INTO provider_model_deletion_render_plan_references(video_render_plan_id, provider_model_id)
    SELECT plan.id, OLD.id
    FROM video_render_plans plan
    WHERE plan.provider_model_id = OLD.id
    ON CONFLICT (video_render_plan_id) DO UPDATE
    SET provider_model_id = EXCLUDED.provider_model_id,
        captured_at = now();

    RETURN OLD;
END;
$$;

CREATE TRIGGER provider_models_capture_deletion
    BEFORE DELETE ON provider_models
    FOR EACH ROW EXECUTE FUNCTION cineweave_capture_provider_model_deletion();

-- Provider model deletion is an administrative provenance update. It must be
-- allowed for archived generations while all production fields stay immutable.
CREATE OR REPLACE FUNCTION cineweave_enforce_active_production_generation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    active_generation UUID;
BEGIN
    IF TG_OP = 'UPDATE'
       AND TG_TABLE_NAME = 'video_render_plans'
       AND (to_jsonb(NEW) -> 'provider_model_id') IS DISTINCT FROM (to_jsonb(OLD) -> 'provider_model_id')
       AND (to_jsonb(NEW) - 'provider_model_id') = (to_jsonb(OLD) - 'provider_model_id') THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.production_generation_id IS DISTINCT FROM OLD.production_generation_id THEN
        RAISE EXCEPTION 'PRODUCTION_GENERATION_MISMATCH: production_generation_id is immutable'
            USING ERRCODE = '40001';
    END IF;
    SELECT active_video_production_generation_id
    INTO active_generation
    FROM projects
    WHERE id = NEW.project_id;
    IF active_generation IS NULL OR NEW.production_generation_id IS DISTINCT FROM active_generation THEN
        RAISE EXCEPTION 'PRODUCTION_GENERATION_MISMATCH: production generation is no longer active'
            USING ERRCODE = '40001';
    END IF;
    RETURN NEW;
END;
$$;
COMMIT;

-- migration 000038_project_active_script.sql sha256:8c8cbee69a425a00dc51b55a8e8b6d686dcdcb54f1df79d9d71dfa0ecd0114f3
BEGIN;
SET search_path TO public;

ALTER TABLE scripts
    ADD CONSTRAINT scripts_id_project_unique UNIQUE (id, project_id);

ALTER TABLE projects
    ADD COLUMN active_script_id UUID;

UPDATE projects project
SET active_script_id = (
    SELECT script.id
    FROM scripts script
    WHERE script.project_id = project.id
      AND script.current_version_id IS NOT NULL
      AND COALESCE(script.status, 'active') <> 'archived'
    ORDER BY CASE WHEN script.status = 'active' THEN 0 ELSE 1 END,
             script.updated_at DESC,
             script.created_at DESC,
             script.id
    LIMIT 1
);

ALTER TABLE projects
    ADD CONSTRAINT projects_active_script_project_fk
    FOREIGN KEY (active_script_id, id)
    REFERENCES scripts(id, project_id)
    ON DELETE SET NULL (active_script_id);

CREATE INDEX projects_active_script_idx
    ON projects(active_script_id)
    WHERE active_script_id IS NOT NULL;
COMMIT;

-- migration 000039_membership_authorization_version.sql sha256:6065ad3dc550c47f6c35bfe685eb6f06cdd3a23d40dbb6e49fd4f63c7f5c8683
BEGIN;
SET search_path TO public;

ALTER TABLE organization_members
    ADD COLUMN authorization_version BIGINT NOT NULL DEFAULT 1,
    ADD CONSTRAINT organization_members_authorization_version_positive
        CHECK (authorization_version > 0);

ALTER TABLE auth_sessions
    ADD COLUMN membership_authorization_version BIGINT;

UPDATE auth_sessions
SET revoked_at = COALESCE(revoked_at, now())
WHERE organization_id IS NOT NULL;

UPDATE auth_sessions session
SET membership_authorization_version = COALESCE((
    SELECT membership.authorization_version
    FROM organization_members membership
    WHERE membership.organization_id = session.organization_id
      AND membership.user_id = session.user_id
    LIMIT 1
), 1)
WHERE session.organization_id IS NOT NULL;

UPDATE auth_sessions
SET membership_authorization_version = 1
WHERE organization_id IS NOT NULL
  AND membership_authorization_version IS NULL;

ALTER TABLE auth_sessions
    ADD CONSTRAINT auth_sessions_membership_authorization_version_check CHECK (
        (organization_id IS NULL AND membership_authorization_version IS NULL)
        OR (
            organization_id IS NOT NULL
            AND membership_authorization_version IS NOT NULL
            AND membership_authorization_version > 0
        )
    );

ALTER TABLE auth_organization_selection_nonces
    ADD COLUMN organization_authorization_versions JSONB NOT NULL DEFAULT '{}'::jsonb,
    ADD CONSTRAINT auth_organization_selection_nonces_authorization_versions_check
        CHECK (jsonb_typeof(organization_authorization_versions) = 'object');

UPDATE auth_organization_selection_nonces
SET consumed_at = COALESCE(consumed_at, now());
COMMIT;

-- migration 000040_video_execution_identity_v2.sql sha256:8721fb5d4a0a147b6a32e4e2ba2079a53e95064d983743ad7ad96e0a48b71d78
BEGIN;
SET search_path TO public;

ALTER TABLE episode_video_production_items
    ADD COLUMN execution_identity_version SMALLINT NOT NULL DEFAULT 1,
    ADD COLUMN predecessor_video_render_plan_id UUID REFERENCES video_render_plans(id) ON DELETE SET NULL,
    ADD COLUMN execution_plan_bound_at TIMESTAMPTZ,
    ADD CONSTRAINT episode_video_production_items_identity_version_check CHECK (
        execution_identity_version IN (1, 2)
    ),
    ADD CONSTRAINT episode_video_production_items_v2_plan_binding_check CHECK (
        execution_identity_version <> 2
        OR video_render_plan_id IS NULL
        OR execution_plan_bound_at IS NOT NULL
    );

CREATE UNIQUE INDEX episode_video_production_items_v2_render_plan_once
    ON episode_video_production_items(video_render_plan_id)
    WHERE execution_identity_version = 2 AND video_render_plan_id IS NOT NULL;

CREATE INDEX episode_video_production_items_v2_attempt_idx
    ON episode_video_production_items(storyboard_shot_id, attempt DESC, created_at DESC)
    WHERE execution_identity_version = 2;

ALTER TABLE video_render_plans
    ADD COLUMN operation_item_id UUID REFERENCES episode_video_production_items(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_attempt INTEGER,
    ADD CONSTRAINT video_render_plans_operation_item_pair_check CHECK (
        (operation_item_id IS NULL) = (operation_item_attempt IS NULL)
    ),
    ADD CONSTRAINT video_render_plans_operation_item_attempt_check CHECK (
        operation_item_attempt IS NULL OR operation_item_attempt > 0
    );

CREATE UNIQUE INDEX video_render_plans_operation_item_once
    ON video_render_plans(operation_item_id)
    WHERE operation_item_id IS NOT NULL;

ALTER TABLE provider_async_tasks
    ADD COLUMN operation_id UUID REFERENCES episode_video_production_checkpoints(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_id UUID REFERENCES episode_video_production_items(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_attempt INTEGER,
    ADD COLUMN request_hash TEXT,
    ADD CONSTRAINT provider_async_tasks_operation_item_pair_check CHECK (
        (operation_item_id IS NULL) = (operation_item_attempt IS NULL)
    ),
    ADD CONSTRAINT provider_async_tasks_operation_item_attempt_check CHECK (
        operation_item_attempt IS NULL OR operation_item_attempt > 0
    ),
    ADD CONSTRAINT provider_async_tasks_request_hash_check CHECK (
        request_hash IS NULL OR btrim(request_hash) <> ''
    );

UPDATE provider_async_tasks task
SET request_hash = request.request_hash
FROM provider_requests request
WHERE request.id = task.provider_request_id
  AND task.request_hash IS NULL;

UPDATE provider_async_tasks task
SET operation_id = batch.checkpoint_id
FROM episode_video_production_items item
JOIN episode_video_production_batches batch ON batch.id = item.batch_id
WHERE item.id = task.operation_item_id
  AND task.operation_id IS NULL;

CREATE INDEX provider_async_tasks_operation_item_idx
    ON provider_async_tasks(operation_id, operation_item_id, status, created_at DESC)
    WHERE operation_item_id IS NOT NULL;

CREATE UNIQUE INDEX provider_async_tasks_segment_request_once
    ON provider_async_tasks(video_render_segment_id, request_hash)
    WHERE video_render_segment_id IS NOT NULL AND request_hash IS NOT NULL;

ALTER TABLE provider_requests
    -- Provider requests are the audit envelope for attempted identities. Keep the
    -- submitted UUIDs even when exact plan validation rejects the request.
    ADD COLUMN operation_id UUID,
    ADD COLUMN operation_item_id UUID,
    ADD COLUMN operation_item_attempt INTEGER,
    ADD COLUMN video_render_plan_id UUID,
    ADD COLUMN video_render_segment_id UUID,
    ADD CONSTRAINT provider_requests_operation_item_pair_check CHECK (
        (operation_item_id IS NULL) = (operation_item_attempt IS NULL)
    ),
    ADD CONSTRAINT provider_requests_operation_item_attempt_check CHECK (
        operation_item_attempt IS NULL OR operation_item_attempt > 0
    );

ALTER TABLE provider_call_logs
    ADD COLUMN operation_id UUID REFERENCES episode_video_production_checkpoints(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_id UUID REFERENCES episode_video_production_items(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_attempt INTEGER,
    ADD COLUMN video_render_plan_id UUID REFERENCES video_render_plans(id) ON DELETE SET NULL,
    ADD COLUMN video_render_segment_id UUID REFERENCES video_render_segments(id) ON DELETE SET NULL,
    ADD CONSTRAINT provider_call_logs_operation_item_pair_check CHECK (
        (operation_item_id IS NULL) = (operation_item_attempt IS NULL)
    ),
    ADD CONSTRAINT provider_call_logs_operation_item_attempt_check CHECK (
        operation_item_attempt IS NULL OR operation_item_attempt > 0
    );

ALTER TABLE cost_records
    ADD COLUMN operation_id UUID REFERENCES episode_video_production_checkpoints(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_id UUID REFERENCES episode_video_production_items(id) ON DELETE SET NULL,
    ADD COLUMN operation_item_attempt INTEGER,
    ADD COLUMN video_render_plan_id UUID REFERENCES video_render_plans(id) ON DELETE SET NULL,
    ADD COLUMN video_render_segment_id UUID REFERENCES video_render_segments(id) ON DELETE SET NULL,
    ADD CONSTRAINT cost_records_operation_item_pair_check CHECK (
        (operation_item_id IS NULL) = (operation_item_attempt IS NULL)
    ),
    ADD CONSTRAINT cost_records_operation_item_attempt_check CHECK (
        operation_item_attempt IS NULL OR operation_item_attempt > 0
    );

UPDATE provider_requests request
SET operation_id = checkpoint.id,
    operation_item_id = task.operation_item_id,
    operation_item_attempt = task.operation_item_attempt,
    video_render_plan_id = task.video_render_plan_id,
    video_render_segment_id = task.video_render_segment_id
FROM provider_async_tasks task
JOIN episode_video_production_items item ON item.id = task.operation_item_id
JOIN episode_video_production_batches batch ON batch.id = item.batch_id
JOIN episode_video_production_checkpoints checkpoint ON checkpoint.id = batch.checkpoint_id
WHERE request.id = task.provider_request_id
  AND task.operation_item_id IS NOT NULL;

UPDATE provider_call_logs call
SET operation_id = request.operation_id,
    operation_item_id = request.operation_item_id,
    operation_item_attempt = request.operation_item_attempt,
    video_render_plan_id = request.video_render_plan_id,
    video_render_segment_id = request.video_render_segment_id
FROM provider_requests request
WHERE request.id = call.provider_request_id
  AND request.operation_item_id IS NOT NULL;

UPDATE cost_records cost
SET operation_id = call.operation_id,
    operation_item_id = call.operation_item_id,
    operation_item_attempt = call.operation_item_attempt,
    video_render_plan_id = call.video_render_plan_id,
    video_render_segment_id = call.video_render_segment_id
FROM provider_call_logs call
WHERE call.id = cost.provider_call_id
  AND call.operation_item_id IS NOT NULL;

CREATE INDEX provider_requests_operation_item_idx
    ON provider_requests(operation_item_id, operation_item_attempt, created_at DESC)
    WHERE operation_item_id IS NOT NULL;

CREATE INDEX provider_call_logs_operation_item_idx
    ON provider_call_logs(operation_item_id, operation_item_attempt, created_at DESC)
    WHERE operation_item_id IS NOT NULL;

CREATE INDEX cost_records_operation_item_idx
    ON cost_records(operation_item_id, operation_item_attempt, created_at DESC)
    WHERE operation_item_id IS NOT NULL;
COMMIT;

