    owning_batch derived_asset_batches%ROWTYPE;
    duplicate_source derived_asset_request_items%ROWTYPE;
    retry_source derived_asset_request_items%ROWTYPE;
    retry_source_batch derived_asset_batches%ROWTYPE;
